"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Grouping page: Mingei — desk</title>\n<script src=\"./support.js\"></script>\n</head>\n<body>\n<x-dc>\n<helmet>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&amp;family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&amp;family=Noto+Serif+JP:wght@500&amp;display=swap\">\n<style>\nbody{margin:0;background:#F3EDE3;font-family:'IBM Plex Sans',system-ui,sans-serif;color:#1E1A15}\na{color:#2F4470}a:hover{color:#1C2B4A}\nbutton{font-family:inherit}\n</style>\n</helmet>\n<div style=\"width: 1440px; height: 900px; box-sizing: border-box; display: flex; flex-direction: column; background: #F3EDE3; color: #1E1A15; font-family: 'IBM Plex Sans', system-ui, sans-serif;\">\n\n  <header style=\"height: 56px; box-sizing: border-box; padding: 0 24px; display: flex; align-items: center; gap: 24px; border-bottom: 1px solid #DCD3C4; background: #FBF8F2;\">\n    <div style=\"display: flex; flex-direction: column; gap: 2px; width: 260px;\">\n      <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.04em; text-transform: uppercase;\">Module F1 · Atlas</span>\n",
"      <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 18px; font-weight: 600;\">Histories of making</span>\n    </div>\n    <nav aria-label=\"Breadcrumb\" style=\"flex-grow: 1; display: flex; align-items: center; gap: 8px; font-size: 13px; color: #574E42;\">\n      <a href=\"#\">Atlas</a><span aria-hidden=\"true\">/</span><a href=\"#\">Groupings</a><span aria-hidden=\"true\">/</span><a href=\"#\">Movements</a><span aria-hidden=\"true\">/</span><span style=\"color: #1E1A15;\">Mingei</span>\n    </nav>\n    <div style=\"display: flex; gap: 10px; align-items: center;\">\n      <div role=\"group\" aria-label=\"Atlas surfaces\" style=\"display: flex; gap: 4px; background: #FFFFFF; border: 1px solid #DCD3C4; border-radius: 10px; padding: 4px;\">\n        <button type=\"button\" style=\"height: 30px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #574E42; font-size: 13px;\">Place</button>\n        <button type=\"button\" style=\"height: 30px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #574E42; font-size: 13px;\">Time</button>\n",
"        <button type=\"button\" style=\"height: 30px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #574E42; font-size: 13px;\">Connections</button>\n        <button type=\"button\" aria-pressed=\"true\" style=\"height: 30px; padding: 0 12px; border: 0; border-radius: 7px; background: #1E1A15; color: #FBF8F2; font-size: 13px;\">Groupings</button>\n      </div>\n      <span style=\"font-size: 13px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; color: #574E42;\">Practice</span>\n    </div>\n  </header>\n\n  <div style=\"flex-grow: 1; display: flex; min-height: 0;\">\n\n    <aside aria-label=\"Grouping card\" style=\"width: 380px; box-sizing: border-box; background: #FBF8F2; border-right: 1px solid #DCD3C4; padding: 24px 26px; display: flex; flex-direction: column; gap: 16px;\">\n      <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.04em;\">GROUPING · MOVEMENT</span>\n      <div style=\"display: flex; align-items: baseline; gap: 12px;\">\n        <h1 style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 40px; line-height: 1; font-weight: 500;\">Mingei</h1>\n",
"        <span lang=\"ja\" style=\"font-family: 'Noto Serif JP', serif; font-size: 24px; color: #574E42;\">民藝</span>\n      </div>\n      <p style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 18px; line-height: 1.4;\">A 1925 name for everyday crafts, made famous by named makers.</p>\n      <dl style=\"margin: 0; display: flex; flex-direction: column; gap: 12px; font-size: 13px; line-height: 1.5;\">\n        <div><dt style=\"font-size: 11.5px; color: #6B6154; letter-spacing: 0.03em;\">NAMED BY</dt><dd style=\"margin: 2px 0 0;\">Yanagi Sōetsu, with the potters Kawai Kanjirō and Hamada Shōji, in 1925: “folk crafts” or “common crafts”</dd></div>\n        <div><dt style=\"font-size: 11.5px; color: #6B6154; letter-spacing: 0.03em;\">SPAN AND PLACES</dt><dd style=\"margin: 2px 0 0;\">Japan, 1925 to today; collecting in Tōhoku, Kyūshū and Okinawa; Joseon crafts exhibited; Ainu and Taiwanese work shown</dd></div>\n        <div><dt style=\"font-size: 11.5px; color: #6B6154; letter-spacing: 0.03em;\">MEMBERSHIP</dt>\n          <dd style=\"margin: 4px 0 0; display: flex; flex-direction: column; gap: 6px;\">\n",
"            <span style=\"display: flex; gap: 10px; align-items: center;\"><svg width=\"40\" height=\"10\" aria-hidden=\"true\"><line x1=\"0\" y1=\"5\" x2=\"40\" y2=\"5\" stroke=\"#1E1A15\" stroke-width=\"2.5\"></line></svg>Documented: the founders and their association</span>\n            <span style=\"display: flex; gap: 10px; align-items: center;\"><svg width=\"40\" height=\"10\" aria-hidden=\"true\"><line x1=\"0\" y1=\"5\" x2=\"40\" y2=\"5\" stroke=\"#1E1A15\" stroke-width=\"2.5\" stroke-dasharray=\"14 5\"></line></svg>Claimed: the anonymous makers it collected</span>\n          </dd>\n        </div>\n        <div><dt style=\"font-size: 11.5px; color: #6B6154; letter-spacing: 0.03em;\">LEAVES OUT</dt><dd style=\"margin: 2px 0 0;\">The makers it championed never chose the label; Korean, Okinawan, Ainu and Taiwanese work was gathered into a Japanese category</dd></div>\n      </dl>\n      <div style=\"margin-top: auto; padding: 12px 14px; border: 1px solid #DCD3C4; border-radius: 8px; background: #FFFFFF; font-size: 12.5px; line-height: 1.5; color: #3A332B;\">\n        <span style=\"display: block; font-size: 11.5px; color: #6B6154; margin-bottom: 4px;\">USED IN</span>\n",
"        F1.20 Movements and revivals · F1.8 East Asia · Compare, with Arts and Crafts\n      </div>\n    </aside>\n\n    <main aria-label=\"Walk\" style=\"width: 620px; box-sizing: border-box; padding: 22px 28px; display: flex; flex-direction: column; gap: 14px;\">\n      <div aria-label=\"Walk progress\" style=\"display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px;\">\n        <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n        <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n        <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n        <span style=\"height: 4px; border-radius: 2px; background: {{accent}};\"></span>\n        <span style=\"height: 4px; border-radius: 2px; background: #D2C6B0;\"></span>\n        <span style=\"height: 4px; border-radius: 2px; background: #D2C6B0;\"></span>\n        <span style=\"height: 4px; border-radius: 2px; background: #D2C6B0;\"></span>\n      </div>\n      <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.03em;\">STEP 4 OF 7 · NAMED MAKERS</span>\n",
"      <p style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 25px; line-height: 1.3;\">Hamada, Kawai and the English potter Bernard Leach become the movement's public faces.</p>\n      <p style=\"margin: 0; font-size: 15px; line-height: 1.55; color: #3A332B;\">Cleveland's record notes that Hamada did not sign his pieces, and that Japan named him a Living National Treasure in 1955.</p>\n      <div style=\"display: flex; gap: 8px; align-items: center; font-size: 12px; color: #574E42;\">\n        <svg width=\"28\" height=\"10\" aria-hidden=\"true\"><line x1=\"0\" y1=\"5\" x2=\"28\" y2=\"5\" stroke=\"#574E42\" stroke-width=\"2.5\"></line></svg>documented · Cleveland Museum of Art, record 2000.145\n      </div>\n      <div style=\"display: flex; gap: 12px; padding: 12px 14px; background: #FBF8F2; border: 1px solid #DCD3C4; border-radius: 10px;\">\n        <span aria-hidden=\"true\" style=\"flex-shrink: 0; width: 30px; height: 30px; border-radius: 50%; background: #2F4470; color: #FBF8F2; font-family: 'Newsreader', Georgia, serif; font-size: 15px; display: flex; align-items: center; justify-content: center;\">H</span>\n",
"        <span style=\"font-size: 14px; line-height: 1.5;\">Step 3 praised the unknown maker; step 4 is how the movement became known. Which of the two would you put on the label of a Mashiko bowl, and why?</span>\n      </div>\n\n      <section aria-label=\"Members on the map and timeline\" style=\"display: flex; gap: 12px; height: 256px;\">\n        <div role=\"img\" aria-label=\"Schematic map of Japan, Korea, Okinawa and Taiwan with Mashiko, Kyoto and Tokyo lit, and St Ives in an inset\" style=\"flex: 0 0 290px; border-radius: 8px; background: #EFE8DC; position: relative; overflow: hidden;\">\n          <svg width=\"290\" height=\"256\" viewBox=\"0 0 290 256\" aria-hidden=\"true\">\n            <path d=\"M92 70 Q 102 58 110 66 Q 116 84 108 104 Q 100 116 94 108 Q 88 92 92 70 Z\" fill=\"#DCD3C4\" stroke=\"#C9BCA4\"></path>\n            <path d=\"M150 40 Q 176 44 196 70 Q 214 96 206 118 Q 192 138 170 150 Q 150 160 138 174 Q 128 168 136 150 Q 152 132 170 116 Q 186 96 170 72 Q 156 56 150 40 Z\" fill=\"#DCD3C4\" stroke=\"#C9BCA4\"></path>\n            <circle cx=\"118\" cy=\"214\" r=\"3\" fill=\"#C9BCA4\"></circle>\n            <circle cx=\"60\" cy=\"238\" r=\"4\" fill=\"#C9BCA4\"></circle>\n",
"            <circle cx=\"104\" cy=\"92\" r=\"5\" fill=\"#8C8173\"></circle>\n            <circle cx=\"196\" cy=\"100\" r=\"7\" fill=\"{{accent}}\" stroke=\"#FBF8F2\" stroke-width=\"2\"></circle>\n            <circle cx=\"168\" cy=\"132\" r=\"7\" fill=\"{{accent}}\" stroke=\"#FBF8F2\" stroke-width=\"2\"></circle>\n            <circle cx=\"190\" cy=\"112\" r=\"5\" fill=\"#8C8173\"></circle>\n          </svg>\n          <span style=\"position: absolute; left: 206px; top: 90px; font-size: 11.5px; background: #FBF8F2; padding: 1px 5px; border-radius: 4px;\">Mashiko</span>\n          <span style=\"position: absolute; left: 112px; top: 132px; font-size: 11.5px; background: #FBF8F2; padding: 1px 5px; border-radius: 4px;\">Kyoto</span>\n          <span style=\"position: absolute; left: 204px; top: 116px; font-size: 11px; color: #574E42;\">Tokyo</span>\n          <span style=\"position: absolute; left: 50px; top: 80px; font-size: 11px; color: #574E42;\">Seoul</span>\n          <span style=\"position: absolute; left: 126px; top: 206px; font-size: 11px; color: #574E42;\">Okinawa</span>\n          <span style=\"position: absolute; left: 70px; top: 230px; font-size: 11px; color: #574E42;\">Taiwan</span>\n",
"          <span style=\"position: absolute; left: 10px; top: 10px; width: 70px; height: 48px; box-sizing: border-box; border: 1px solid #C9BCA4; border-radius: 6px; background: #F3EDE3; font-size: 11px; color: #574E42; padding: 4px 6px; line-height: 1.3;\">Inset<br><span style=\"color: {{accent}}; font-weight: 600;\">St Ives</span></span>\n          <span style=\"position: absolute; right: 8px; bottom: 6px; font-size: 10.5px; color: #6B6154;\">[Schematic]</span>\n        </div>\n        <div role=\"img\" aria-label=\"Timeline 1910 to 1960 with the word in 1925, the museum in 1936 and Hamada's designation in 1955 lit\" style=\"flex-grow: 1; border-radius: 8px; background: #FBF8F2; border: 1px solid #DCD3C4; position: relative; padding: 12px 14px; box-sizing: border-box;\">\n          <span style=\"font-size: 11.5px; color: #6B6154; letter-spacing: 0.03em;\">TIMELINE · 1910–1960</span>\n          <div style=\"position: absolute; left: 14px; right: 14px; top: 200px; height: 2px; background: #C9BCA4;\"></div>\n",
"          <div style=\"position: absolute; left: 14px; right: 14px; top: 208px; display: flex; justify-content: space-between; font-size: 11px; color: #6B6154;\"><span>1910</span><span>1920</span><span>1930</span><span>1940</span><span>1950</span><span>1960</span></div>\n          <div style=\"position: absolute; left: 30px; top: 52px; width: 238px; height: 10px; border-radius: 5px; background: {{accent}}; opacity: 0.85;\"></div>\n          <span style=\"position: absolute; left: 30px; top: 36px; font-size: 11.5px;\">Hamada Shōji, 1894–1978</span>\n          <div style=\"position: absolute; left: 14px; top: 96px; width: 250px; height: 10px; border-radius: 5px; background: #D2C6B0;\"></div>\n          <span style=\"position: absolute; left: 14px; top: 80px; font-size: 11.5px; color: #574E42;\">Leach Pottery, St Ives, from 1920</span>\n          <span style=\"position: absolute; left: 74px; top: 150px; width: 10px; height: 10px; border-radius: 50%; background: #8C8173;\"></span>\n          <span style=\"position: absolute; left: 60px; top: 166px; font-size: 11px; color: #574E42;\">1925 word</span>\n",
"          <span style=\"position: absolute; left: 130px; top: 150px; width: 10px; height: 10px; border-radius: 50%; background: #8C8173;\"></span>\n          <span style=\"position: absolute; left: 112px; top: 132px; font-size: 11px; color: #574E42;\">1936 museum</span>\n          <span style=\"position: absolute; left: 226px; top: 146px; width: 16px; height: 16px; border-radius: 50%; background: {{accent}}; border: 2px solid #FBF8F2;\"></span>\n          <span style=\"position: absolute; left: 196px; top: 168px; font-size: 11px; font-weight: 600;\">1955 LNT</span>\n        </div>\n      </section>\n\n      <div style=\"display: flex; gap: 8px; margin-top: auto;\">\n        <button type=\"button\" style=\"flex-grow: 1; height: 46px; border: 1px solid #DCD3C4; border-radius: 10px; background: #FFFFFF; font-size: 14px; color: #1E1A15;\">Step 3 · The unknown maker</button>\n        <button type=\"button\" style=\"flex-grow: 2; height: 46px; border: 0; border-radius: 10px; background: {{accent}}; color: #FFFFFF; font-size: 14px; font-weight: 500;\">Next · The museum, 1936</button>\n      </div>\n    </main>\n\n",
"    <aside aria-label=\"Members and more\" style=\"width: 440px; box-sizing: border-box; background: #FBF8F2; border-left: 1px solid #DCD3C4; padding: 20px 22px; display: flex; flex-direction: column; gap: 14px;\">\n      <div role=\"tablist\" aria-label=\"Grouping sections\" style=\"display: flex; gap: 2px; border-bottom: 1px solid #DCD3C4;\">\n        <button type=\"button\" role=\"tab\" aria-selected=\"true\" style=\"height: 36px; padding: 0 10px; border: 0; border-bottom: 2px solid {{accent}}; background: transparent; font-size: 13.5px; color: #1E1A15; font-weight: 600;\">Members · 10</button>\n        <button type=\"button\" role=\"tab\" aria-selected=\"false\" style=\"height: 36px; padding: 0 10px; border: 0; border-bottom: 2px solid transparent; background: transparent; font-size: 13.5px; color: #574E42;\">Neighbours</button>\n        <button type=\"button\" role=\"tab\" aria-selected=\"false\" style=\"height: 36px; padding: 0 10px; border: 0; border-bottom: 2px solid transparent; background: transparent; font-size: 13.5px; color: #574E42;\">Afterlives</button>\n",
"        <button type=\"button\" role=\"tab\" aria-selected=\"false\" style=\"height: 36px; padding: 0 10px; border: 0; border-bottom: 2px solid transparent; background: transparent; font-size: 13.5px; color: #574E42;\">What is argued</button>\n      </div>\n      <div style=\"display: flex; gap: 6px; align-items: center; font-size: 12px; color: #6B6154;\">\n        Lens\n        <button type=\"button\" aria-pressed=\"true\" style=\"height: 26px; padding: 0 9px; border: 1px solid #2F4470; border-radius: 999px; background: #FFFFFF; color: #2F4470; font-size: 12px;\">Labour and credit</button>\n        <button type=\"button\" style=\"height: 26px; padding: 0 9px; border: 1px solid #DCD3C4; border-radius: 999px; background: transparent; color: #574E42; font-size: 12px;\">Material</button>\n        <button type=\"button\" style=\"height: 26px; padding: 0 9px; border: 1px solid #DCD3C4; border-radius: 999px; background: transparent; color: #574E42; font-size: 12px;\">Place</button>\n      </div>\n\n      <div style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px;\">\n        <article style=\"border: 2px dashed #8C8173; border-radius: 8px; background: #FFFFFF; overflow: hidden;\">\n",
"          <div role=\"img\" aria-label=\"Image placeholder: Joseon jar\" style=\"height: 84px; background: repeating-linear-gradient(135deg, #D8CDB9 0 10px, #D2C6B0 10px 20px);\"></div>\n          <div style=\"padding: 8px 10px; font-size: 12px; line-height: 1.4;\"><span style=\"font-weight: 600;\">Jar with scroll design</span><br><span style=\"color: #574E42;\">Joseon, 1400s · Cleveland 1963.505 · CC0</span></div>\n        </article>\n        <article style=\"border: 2px dashed #8C8173; border-radius: 8px; background: #FFFFFF; overflow: hidden;\">\n          <div role=\"img\" aria-label=\"Image placeholder: Ōtsu-e painting\" style=\"height: 84px; background: repeating-linear-gradient(135deg, #D8CDB9 0 10px, #D2C6B0 10px 20px);\"></div>\n          <div style=\"padding: 8px 10px; font-size: 12px; line-height: 1.4;\"><span style=\"font-weight: 600;\">Woman as an Itinerant Monk</span><br><span style=\"color: #574E42;\">Ōtsu-e, c. 1700 · Cleveland 1983.9 · CC0</span></div>\n        </article>\n        <article style=\"border: 2px solid {{accent}}; border-radius: 8px; background: #FFFFFF; overflow: hidden;\">\n",
"          <div style=\"height: 84px; background: #F3EDE3; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; font-size: 11.5px; color: #574E42;\">\n            <span style=\"font-weight: 600; color: #1E1A15;\">In copyright</span>\n            <a href=\"#\">View at Cleveland</a>\n          </div>\n          <div style=\"padding: 8px 10px; font-size: 12px; line-height: 1.4;\"><span style=\"font-weight: 600;\">Rectangular Bottle Vase</span><br><span style=\"color: #574E42;\">Hamada Shōji · Cleveland 2000.145</span></div>\n        </article>\n        <article style=\"border: 2px solid #1E1A15; border-radius: 8px; background: #FFFFFF; overflow: hidden;\">\n          <div style=\"height: 84px; background: #EFE8DC; display: flex; align-items: center; justify-content: center; font-size: 11.5px; color: #574E42;\">Place</div>\n          <div style=\"padding: 8px 10px; font-size: 12px; line-height: 1.4;\"><span style=\"font-weight: 600;\">Japan Folk Crafts Museum</span><br><span style=\"color: #574E42;\">Komaba, Tokyo · 1936</span></div>\n        </article>\n      </div>\n      <a href=\"#\" style=\"font-size: 13px;\">6 more members: people, a town, a technique</a>\n\n",
"      <p style=\"margin: 0; padding: 10px 12px; background: #F3EDE3; border-radius: 8px; font-size: 12.5px; line-height: 1.5; color: #3A332B;\">Open images show only the older, anonymous work the movement collected. The named makers' work is in copyright and appears by link.</p>\n\n      <div style=\"margin-top: auto; padding: 12px 14px; border: 1px solid {{accent}}; border-radius: 8px; background: #FFFFFF; font-size: 13px; line-height: 1.5;\">\n        <span style=\"display: block; font-size: 11.5px; color: #6B6154; margin-bottom: 4px;\">APPLY · F1.20 · {{laneLabel}}</span>\n        {{applyText}}\n      </div>\n    </aside>\n  </div>\n</div>\n</x-dc>\n<script type=\"text/x-dc\" data-dc-script data-props='{\"accent\":{\"editor\":\"color\",\"default\":\"#A0431F\",\"options\":[\"#A0431F\",\"#2F4470\",\"#5B6B2E\",\"#7A4B8C\"]},\"lane\":{\"editor\":\"enum\",\"options\":[\"Maker\",\"Briefer\"],\"default\":\"Maker\"},\"$preview\":{\"width\":1440,\"height\":900}}'>\nclass Component extends DCLogic {\n  renderVals() {\n    const accent = this.props.accent ?? '#A0431F';\n    const lane = this.props.lane ?? 'Maker';\n    return {\n      accent,\n      laneLabel: lane.toUpperCase(),\n      applyText: lane === 'Maker'\n",
"        ? 'Name one anonymous tradition your work draws on, and write how you will credit it without turning it into a style label.'\n        : 'Write the credit line a “mingei-style” product must carry: who made it, where, and whether “mingei” is the maker’s word or the brand’s.'\n    };\n  }\n}\n</script>\n</body>\n</html>\n"
],
