"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Grouping page: Nok — phone</title>\n<script src=\"./support.js\"></script>\n</head>\n<body>\n<x-dc>\n<helmet>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&amp;family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&amp;display=swap\">\n<style>\nbody{margin:0;background:#F3EDE3;font-family:'IBM Plex Sans',system-ui,sans-serif;color:#1E1A15}\na{color:#2F4470}a:hover{color:#1C2B4A}\nbutton{font-family:inherit}\n</style>\n</helmet>\n<div style=\"width: 390px; height: 844px; box-sizing: border-box; display: flex; flex-direction: column; background: #F3EDE3; color: #1E1A15; font-family: 'IBM Plex Sans', system-ui, sans-serif;\">\n\n  <header style=\"height: 52px; box-sizing: border-box; padding: 0 12px; display: flex; align-items: center; gap: 8px; background: #FBF8F2; border-bottom: 1px solid #DCD3C4;\">\n    <button type=\"button\" aria-label=\"Back to groupings\" style=\"width: 44px; height: 44px; border: 0; background: transparent; display: flex; align-items: center; justify-content: center;\">\n",
"      <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#1E1A15\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M15 5l-7 7 7 7\"></path></svg>\n    </button>\n    <span style=\"flex-grow: 1; font-size: 13px; color: #574E42;\">Atlas · Groupings</span>\n    <span style=\"font-size: 12px; padding: 5px 9px; border: 1px solid #DCD3C4; border-radius: 999px; color: #574E42;\">Members · 9</span>\n  </header>\n\n  <section aria-label=\"Grouping card\" style=\"padding: 12px 16px 0; display: flex; flex-direction: column; gap: 6px;\">\n    <span style=\"font-size: 11.5px; color: #6B6154; letter-spacing: 0.04em;\">ARCHAEOLOGICAL CULTURE</span>\n    <div style=\"display: flex; align-items: baseline; gap: 10px;\">\n      <h1 style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 30px; line-height: 1; font-weight: 500;\">Nok</h1>\n      <span style=\"font-size: 12.5px; color: #574E42;\">central Nigeria · c. 1500 BCE to the turn of the era</span>\n    </div>\n",
"    <div style=\"display: flex; gap: 8px; align-items: flex-start; padding: 8px 10px; border: 1px solid #C9BCA4; border-radius: 8px; background: #FBF8F2; font-size: 12px; line-height: 1.45; color: #3A332B;\">\n      <svg width=\"26\" height=\"12\" aria-hidden=\"true\" style=\"flex-shrink: 0; margin-top: 3px;\"><line x1=\"0\" y1=\"3\" x2=\"26\" y2=\"3\" stroke=\"#1E1A15\" stroke-width=\"2\" stroke-dasharray=\"6 5\"></line><line x1=\"0\" y1=\"10\" x2=\"26\" y2=\"10\" stroke=\"#1E1A15\" stroke-width=\"2\" stroke-dasharray=\"6 5\"></line></svg>\n      <span><span style=\"font-weight: 600;\">Membership contested for museum pieces.</span> Most carry “Nok style” and no findspot.</span>\n    </div>\n  </section>\n\n  <div aria-label=\"Walk progress\" style=\"display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; padding: 10px 16px 0;\">\n    <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n    <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n    <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n    <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n",
"    <span style=\"height: 4px; border-radius: 2px; background: #8C8173;\"></span>\n    <span style=\"height: 4px; border-radius: 2px; background: {{accent}};\"></span>\n    <span style=\"height: 4px; border-radius: 2px; background: #D2C6B0;\"></span>\n  </div>\n\n  <section aria-label=\"Members on the timeline\" style=\"padding: 10px 16px 0;\">\n    <div role=\"img\" aria-label=\"Timeline from 1500 BCE to 700 CE: Nok's early, main and late phases end at the turn of the era; the Cleveland head's date range, 20 to 620 CE, lies after it\" style=\"height: 118px; border-radius: 8px; background: #FBF8F2; border: 1px solid #DCD3C4; position: relative; box-sizing: border-box;\">\n      <span style=\"position: absolute; left: 10px; top: 8px; font-size: 11px; color: #6B6154; letter-spacing: 0.03em;\">TIMELINE · 1500 BCE – 700 CE</span>\n      <div style=\"position: absolute; left: 10px; width: 94px; top: 36px; height: 10px; border-radius: 5px; background: #D2C6B0;\"></div>\n      <div style=\"position: absolute; left: 104px; width: 88px; top: 36px; height: 10px; background: #8C8173;\"></div>\n",
"      <div style=\"position: absolute; left: 192px; width: 44px; top: 36px; height: 10px; border-radius: 0 5px 5px 0; background: #D2C6B0;\"></div>\n      <span style=\"position: absolute; left: 10px; top: 50px; font-size: 10.5px; color: #574E42;\">early</span>\n      <span style=\"position: absolute; left: 116px; top: 50px; font-size: 10.5px; color: #1E1A15; font-weight: 600;\">main: figures, iron</span>\n      <span style=\"position: absolute; left: 196px; top: 50px; font-size: 10.5px; color: #574E42;\">late</span>\n      <div style=\"position: absolute; left: 238px; top: 26px; bottom: 30px; width: 0; border-left: 1px dashed #574E42;\"></div>\n      <div style=\"position: absolute; left: 243px; width: 93px; top: 70px; height: 10px; border-radius: 5px; border: 2px dashed {{accent}}; box-sizing: border-box;\"></div>\n      <span style=\"position: absolute; left: 246px; top: 84px; font-size: 10.5px; color: {{accent}}; font-weight: 600;\">the head, 20–620 CE</span>\n",
"      <span style=\"position: absolute; left: 10px; bottom: 14px; font-size: 10px; color: #6B6154;\">1500 BCE</span><span style=\"position: absolute; left: 94px; bottom: 14px; font-size: 10px; color: #6B6154;\">900</span><span style=\"position: absolute; left: 186px; bottom: 14px; font-size: 10px; color: #6B6154;\">300</span><span style=\"position: absolute; left: 236px; bottom: 14px; font-size: 10px; color: #6B6154;\">0</span><span style=\"position: absolute; right: 10px; bottom: 14px; font-size: 10px; color: #6B6154;\">700 CE</span>\n    </div>\n  </section>\n\n  <main style=\"flex-grow: 1; padding: 12px 16px 0; display: flex; flex-direction: column; gap: 10px; min-height: 0;\">\n    <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.03em;\">STEP 6 OF 7 · A HEAD THAT IS NOT NOK</span>\n    <p style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 19px; line-height: 1.4;\">Cleveland's “Nok-culture style” head is dated 20–620 CE, after the culture ended.</p>\n    <p style=\"margin: 0; font-size: 14px; line-height: 1.5; color: #3A332B;\">It was first recorded with a Brussels dealer by 1994. The Atlas shows it as a case, not as Nok.</p>\n",
"    <div style=\"display: flex; gap: 8px; align-items: center; font-size: 12px; color: #574E42;\">\n      <svg width=\"28\" height=\"10\" aria-hidden=\"true\"><line x1=\"0\" y1=\"5\" x2=\"28\" y2=\"5\" stroke=\"#574E42\" stroke-width=\"2.5\"></line></svg>documented · Cleveland 1995.21; Franke 2016\n    </div>\n    <div style=\"display: flex; gap: 6px; flex-wrap: wrap;\">\n      <span style=\"font-size: 12px; padding: 4px 9px; border: 1px dashed {{accent}}; border-radius: 999px; color: #1E1A15;\">WS-X04 · case</span>\n      <span style=\"font-size: 12px; padding: 4px 9px; border: 1px solid #DCD3C4; border-radius: 999px; color: #574E42;\">Nok chronology</span>\n      <span style=\"font-size: 12px; padding: 4px 9px; border: 1px solid #DCD3C4; border-radius: 999px; color: #574E42;\">F1.24 looting</span>\n    </div>\n\n    <div style=\"display: flex; gap: 8px; margin-top: auto; padding-bottom: 12px;\">\n      <button type=\"button\" style=\"flex-grow: 1; height: 48px; border: 1px solid #DCD3C4; border-radius: 10px; background: #FFFFFF; font-size: 15px; color: #1E1A15;\">Step 5</button>\n",
"      <button type=\"button\" style=\"flex-grow: 2; height: 48px; border: 0; border-radius: 10px; background: {{accent}}; color: #FFFFFF; font-size: 15px; font-weight: 600;\">Next: what is argued</button>\n    </div>\n  </main>\n\n  <nav aria-label=\"Sections\" style=\"height: 64px; box-sizing: border-box; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid #DCD3C4; background: #FBF8F2;\">\n    <button type=\"button\" style=\"border: 0; background: transparent; font-size: 12px; color: #574E42; border-top: 2px solid transparent;\">Unit</button>\n    <button type=\"button\" aria-current=\"page\" style=\"border: 0; background: transparent; font-size: 12px; font-weight: 600; color: {{accent}}; border-top: 2px solid {{accent}};\">Atlas</button>\n    <button type=\"button\" style=\"border: 0; background: transparent; font-size: 12px; color: #574E42; border-top: 2px solid transparent;\">Record</button>\n    <button type=\"button\" style=\"border: 0; background: transparent; font-size: 12px; color: #574E42; border-top: 2px solid transparent;\">Historian</button>\n  </nav>\n</div>\n</x-dc>\n",
"<script type=\"text/x-dc\" data-dc-script data-props='{\"accent\":{\"editor\":\"color\",\"default\":\"#A0431F\",\"options\":[\"#A0431F\",\"#2F4470\",\"#5B6B2E\",\"#7A4B8C\"]},\"$preview\":{\"width\":390,\"height\":844}}'>\nclass Component extends DCLogic {\n  renderVals() {\n    return { accent: this.props.accent ?? '#A0431F' };\n  }\n}\n</script>\n</body>\n</html>\n"
],
