"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>Design language — Archive-warm</title>\n<script src=\"./support.js\"></script>\n</head>\n<body>\n<x-dc>\n<helmet>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&amp;family=IBM+Plex+Sans+Arabic:wght@400;500&amp;family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&amp;display=swap\">\n<style>\nbody{margin:0;background:#F3EDE3;font-family:'IBM Plex Sans',system-ui,sans-serif;color:#1E1A15}\n</style>\n</helmet>\n<div style=\"width: 1440px; height: 900px; box-sizing: border-box; padding: 36px 40px; display: flex; flex-direction: column; gap: 24px; background: #F3EDE3; color: #1E1A15; font-family: 'IBM Plex Sans', system-ui, sans-serif;\">\n\n  <header style=\"display: flex; align-items: flex-end; justify-content: space-between; border-bottom: 1px solid #DCD3C4; padding-bottom: 16px;\">\n    <div style=\"display: flex; flex-direction: column; gap: 4px;\">\n      <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.04em;\">DESIGN LANGUAGE · DRAFT 1</span>\n",
"      <h1 style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 34px; font-weight: 500;\">Archive-warm</h1>\n    </div>\n    <p style=\"margin: 0; max-width: 560px; font-size: 14px; line-height: 1.5; color: #574E42;\">Paper, ink and one warm accent, so the objects carry the colour. Dark canvas only for the globe and time-lapse, where routes need to glow. Every line style means something about evidence.</p>\n  </header>\n\n  <div style=\"display: grid; grid-template-columns: 400px 1fr 440px; gap: 40px; flex-grow: 1; min-height: 0;\">\n\n    <section aria-label=\"Colour\" style=\"display: flex; flex-direction: column; gap: 8px;\">\n      <h2 style=\"margin: 0 0 6px; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">COLOUR</h2>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #F3EDE3; border: 1px solid #DCD3C4;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Paper</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#F3EDE3</span><span style=\"font-size: 12px; color: #574E42;\">Page ground</span></div>\n",
"      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #FBF8F2; border: 1px solid #DCD3C4;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Surface</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#FBF8F2</span><span style=\"font-size: 12px; color: #574E42;\">Panels, cards, bars</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #1E1A15;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Ink</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#1E1A15</span><span style=\"font-size: 12px; color: #574E42;\">Text, primary lines</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #574E42;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Ink 2</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#574E42</span><span style=\"font-size: 12px; color: #574E42;\">Secondary text</span></div>\n",
"      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #6B6154;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Ink 3</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#6B6154</span><span style=\"font-size: 12px; color: #574E42;\">Labels, metadata (AA on paper)</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #DCD3C4;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Rule</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#DCD3C4</span><span style=\"font-size: 12px; color: #574E42;\">Dividers, borders</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #A0431F;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Accent</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#A0431F</span><span style=\"font-size: 12px; color: #574E42;\">Current place, main action</span></div>\n",
"      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #2F4470;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Relation</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#2F4470</span><span style=\"font-size: 12px; color: #574E42;\">Links, connections, records</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #15130F;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Dark canvas</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#15130F</span><span style=\"font-size: 12px; color: #574E42;\">Globe, time-lapse only</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #EDE6D8; border: 1px solid #DCD3C4;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Dark text</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#EDE6D8</span><span style=\"font-size: 12px; color: #574E42;\">Text on dark canvas</span></div>\n",
"      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #D9A25C;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Route gold</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#D9A25C</span><span style=\"font-size: 12px; color: #574E42;\">Goods on routes</span></div>\n      <div style=\"display: flex; align-items: center; gap: 12px;\"><span style=\"width: 40px; height: 34px; border-radius: 6px; background: #9FB3D9;\"></span><span style=\"width: 92px; font-size: 13px; font-weight: 500;\">Materials</span><span style=\"width: 72px; font-size: 12px; color: #574E42;\">#9FB3D9</span><span style=\"font-size: 12px; color: #574E42;\">Materials on routes</span></div>\n      <p style=\"margin: 8px 0 0; font-size: 12px; line-height: 1.5; color: #574E42;\">Colour never carries meaning alone: every route and confidence state also has a line style and a text label.</p>\n    </section>\n\n    <section aria-label=\"Type and components\" style=\"display: flex; flex-direction: column; gap: 14px; min-width: 0;\">\n",
"      <h2 style=\"margin: 0; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">TYPE</h2>\n      <div style=\"display: flex; flex-direction: column; gap: 4px;\">\n        <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 44px; line-height: 1.1; font-weight: 500;\">Histories of making</span>\n        <span style=\"font-size: 12px; color: #6B6154;\">Newsreader 500 · 44 / 32 / 26 · titles, stories, the object's voice</span>\n      </div>\n      <div style=\"display: flex; flex-direction: column; gap: 4px;\">\n        <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 20px; line-height: 1.4;\">Iron-working appears across West Africa and the Nile valley in the first millennium BCE.</span>\n        <span style=\"font-size: 12px; color: #6B6154;\">Newsreader 400 · 20 / 1.4 · story text and Historian replies</span>\n      </div>\n      <div style=\"display: flex; flex-direction: column; gap: 4px;\">\n        <span style=\"font-size: 16px; line-height: 1.55; color: #1E1A15;\">Read it before anyone tells you about it. One line each; guesses are the point. The record opens once all three are in.</span>\n",
"        <span style=\"font-size: 12px; color: #6B6154;\">IBM Plex Sans 400 · 16 / 1.55 · interface and instructions · 14 and 12 for secondary and metadata</span>\n      </div>\n      <div style=\"display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 12px 14px; background: #FBF8F2; border-radius: 8px;\">\n        <span style=\"font-size: 12px; color: #6B6154;\">IBM Plex Sans Arabic · right-to-left, mirrored layout</span>\n        <span dir=\"rtl\" lang=\"ar\" style=\"font-family: 'IBM Plex Sans Arabic', sans-serif; font-size: 30px; font-weight: 500;\">تواريخ الصنع</span>\n      </div>\n\n      <h2 style=\"margin: 8px 0 0; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">COMPONENTS IN THESE BOARDS</h2>\n      <div style=\"display: flex; flex-wrap: wrap; gap: 8px;\">\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Module path (35 ticks)</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Atlas view switcher</span>\n",
"        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Lens chip</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Object hotspot</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Time scrubber</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Confidence tag</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Historian bubble</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Lane tabs</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Story card + steps</span>\n",
"        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Stop stepper</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Object card</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Living-practice card</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Content note</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Coverage warning</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Attribution line</span>\n        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Route legend</span>\n",
"        <span style=\"font-size: 12.5px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; background: #FBF8F2;\">Phone bottom nav</span>\n      </div>\n      <p style=\"margin: 0; font-size: 12px; line-height: 1.5; color: #574E42;\">Touch targets 44px minimum on phone, 48px for main actions. Images are labelled placeholders until each record's rights line is cleared.</p>\n    </section>\n\n    <section aria-label=\"Evidence, rings and motion\" style=\"display: flex; flex-direction: column; gap: 14px;\">\n      <h2 style=\"margin: 0; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">CONFIDENCE GRAMMAR</h2>\n      <div style=\"display: flex; flex-direction: column; gap: 10px;\">\n        <div style=\"display: flex; align-items: center; gap: 14px;\">\n          <svg width=\"72\" height=\"12\" aria-hidden=\"true\"><line x1=\"0\" y1=\"6\" x2=\"72\" y2=\"6\" stroke=\"#1E1A15\" stroke-width=\"2.5\"></line></svg>\n          <span style=\"width: 96px; font-size: 13px; font-weight: 500;\">Documented</span><span style=\"font-size: 12px; color: #574E42;\">A primary source says so</span>\n        </div>\n        <div style=\"display: flex; align-items: center; gap: 14px;\">\n",
"          <svg width=\"72\" height=\"12\" aria-hidden=\"true\"><line x1=\"0\" y1=\"6\" x2=\"72\" y2=\"6\" stroke=\"#1E1A15\" stroke-width=\"2.5\" stroke-dasharray=\"14 5\"></line></svg>\n          <span style=\"width: 96px; font-size: 13px; font-weight: 500;\">Probable</span><span style=\"font-size: 12px; color: #574E42;\">Most specialists agree</span>\n        </div>\n        <div style=\"display: flex; align-items: center; gap: 14px;\">\n          <svg width=\"72\" height=\"12\" aria-hidden=\"true\"><line x1=\"0\" y1=\"3\" x2=\"72\" y2=\"3\" stroke=\"#1E1A15\" stroke-width=\"2\" stroke-dasharray=\"6 5\"></line><line x1=\"0\" y1=\"10\" x2=\"72\" y2=\"10\" stroke=\"#1E1A15\" stroke-width=\"2\" stroke-dasharray=\"6 5\"></line></svg>\n          <span style=\"width: 96px; font-size: 13px; font-weight: 500;\">Contested</span><span style=\"font-size: 12px; color: #574E42;\">Two readings, both shown</span>\n        </div>\n        <div style=\"display: flex; align-items: center; gap: 14px;\">\n          <svg width=\"72\" height=\"12\" aria-hidden=\"true\"><line x1=\"1\" y1=\"6\" x2=\"72\" y2=\"6\" stroke=\"#1E1A15\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-dasharray=\"0.1 6\"></line></svg>\n",
"          <span style=\"width: 96px; font-size: 13px; font-weight: 500;\">Interpretive</span><span style=\"font-size: 12px; color: #574E42;\">Our reading, marked as ours</span>\n        </div>\n      </div>\n\n      <h2 style=\"margin: 8px 0 0; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">DATES</h2>\n      <div style=\"display: flex; flex-direction: column; gap: 8px;\">\n        <div style=\"display: flex; align-items: center; gap: 14px;\">\n          <span style=\"width: 150px; height: 8px; border-radius: 4px; background: linear-gradient(90deg, rgba(160,67,31,0) 0%, #A0431F 22%, #A0431F 78%, rgba(160,67,31,0) 100%);\"></span>\n          <span style=\"font-size: 12px; color: #574E42;\">Range with soft ends · \"about 3100–2900 BCE\"</span>\n        </div>\n        <div style=\"display: flex; align-items: center; gap: 14px;\">\n          <span style=\"width: 150px; display: flex; justify-content: center;\"><span style=\"width: 10px; height: 10px; border-radius: 50%; background: #A0431F;\"></span></span>\n          <span style=\"font-size: 12px; color: #574E42;\">Point · only when a source gives the year</span>\n        </div>\n      </div>\n\n",
"      <h2 style=\"margin: 8px 0 0; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">RINGS</h2>\n      <div style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px;\">\n        <div style=\"padding: 10px; border-radius: 8px; background: #FBF8F2; border: 1.5px solid #1E1A15; display: flex; flex-direction: column; gap: 4px;\">\n          <span style=\"font-size: 13px; font-weight: 600;\">Ring 1</span><span style=\"font-size: 12px; color: #574E42;\">Curated and taught</span>\n        </div>\n        <div style=\"padding: 10px; border-radius: 8px; background: #FBF8F2; border: 1px solid #DCD3C4; display: flex; flex-direction: column; gap: 4px;\">\n          <span style=\"font-size: 13px; font-weight: 600;\">Ring 2</span><span style=\"font-size: 12px; color: #574E42;\">Linked, checked</span>\n        </div>\n        <div style=\"padding: 10px; border-radius: 8px; background: transparent; border: 1px dashed #B5A994; display: flex; flex-direction: column; gap: 4px;\">\n          <span style=\"font-size: 13px; font-weight: 600; color: #574E42;\">Ring 3</span><span style=\"font-size: 12px; color: #6B6154;\">Open data, unreviewed</span>\n        </div>\n      </div>\n\n",
"      <h2 style=\"margin: 8px 0 0; font-size: 13px; font-weight: 600; letter-spacing: 0.03em;\">MOTION</h2>\n      <div style=\"display: flex; flex-direction: column; gap: 6px; font-size: 12.5px; line-height: 1.45; color: #3A332B;\">\n        <span>Slow and meaningful: movement shows change over time or along a route, never decoration.</span>\n        <span>Reduced motion swaps animation for stepped states with the same content.</span>\n        <span>Nothing autoplays with sound. Time-lapse starts paused.</span>\n        <span>Parallax layers stay readable when frozen at any point.</span>\n      </div>\n    </section>\n  </div>\n</div>\n</x-dc>\n<script type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":900}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n</script>\n</body>\n</html>\n"
],
